// Contact section logic: toggles submit button based on terms checkbox

class ContactFormController {
  #form: HTMLFormElement;
  #termsCheckbox: HTMLInputElement | null;
  #submitButton: HTMLInputElement | null;
  #errorContainer: HTMLElement | null;
  #errorMessage: string;

  constructor(form: HTMLFormElement) {
    this.#form = form;
    this.#termsCheckbox = this.#form.querySelector<HTMLInputElement>("#terms");
    this.#submitButton = this.#form.querySelector<HTMLInputElement>(
      "input[type='submit']",
    );
    this.#errorContainer = this.#form.querySelector<HTMLElement>(
      ".contact-form__messages",
    );
    this.#errorMessage =
      this.#form.dataset.errorMessage ??
      "Please make sure all mandatory fields are completed and terms accepted.";
    this.#init();
  }

  #init() {
    if (!this.#termsCheckbox || !this.#submitButton) return;
    // Ensure initial state
    this.#updateSubmitState();
    // Listen for changes on terms checkbox
    this.#termsCheckbox.addEventListener("change", () =>
      this.#updateSubmitState(),
    );

    // Validate on button click even when button visually disabled
    this.#submitButton.addEventListener("click", (e) => {
      if (!this.#isFormValid()) {
        e.preventDefault();
      }
    });

    // Client-side validation on submit (extra guard)
    this.#form.addEventListener("submit", (e) => {
      if (!this.#isFormValid()) {
        e.preventDefault();
      }
    });
  }

  #updateSubmitState() {
    const accepted = this.#termsCheckbox?.checked;
    if (!this.#submitButton) return;
    if (accepted) {
      this.#submitButton.classList.remove("disabled");
    } else {
      this.#submitButton.classList.add("disabled");
    }
  }

  #isFormValid(): boolean {
    let valid = true;

    // Reset previous error states
    this.#form
      .querySelectorAll<HTMLElement>(".error")
      .forEach((el) => el.classList.remove("error"));

    // Check built-in validity for required fields
    const requiredFields = this.#form.querySelectorAll<
      HTMLInputElement | HTMLTextAreaElement
    >("[required]");

    requiredFields.forEach((field) => {
      if (!field.checkValidity()) {
        valid = false;
        const wrapper = field.closest<HTMLElement>(".input-checkbox") ?? field;
        wrapper.classList.add("error");
      }
    });

    // Custom check for terms
    if (!this.#termsCheckbox?.checked) {
      valid = false;
      const termsWrapper =
        this.#termsCheckbox?.closest<HTMLElement>(".input-checkbox");
      (termsWrapper ?? this.#termsCheckbox)?.classList.add("error");
    }

    // Show or hide error message
    if (!valid) {
      this.#showError();
    } else {
      this.#clearError();
    }

    return valid;
  }

  #showError() {
    if (!this.#errorContainer) return;
    this.#errorContainer.innerHTML = `<span class="contact-form__messages__error" role="alert">${this.#errorMessage}</span>`;
  }

  #clearError() {
    if (!this.#errorContainer) return;
    this.#errorContainer.innerHTML = "";
  }
}

// Auto-init on load
const contactForms = document.querySelectorAll<HTMLFormElement>(
  "form[action*='contact']",
);
if (contactForms.length) {
  contactForms.forEach((form) => new ContactFormController(form));
}
